INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist DIN 66001 nur für Softwareentwicklung gedacht?', 2, '[{"text": "Nein", "correct": true, "because": "Auch für Prozesse"}, {"text": "Ja", "correct": false, "because": "Breitere Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Symbol steht für Ein-/Ausgabe in DIN 66001?', 3, '[{"text": "Parallelogramm", "correct": true, "because": "Datenfluss darstellen"}, {"text": "Rechteck", "correct": false, "because": "Prozessschritt"}, {"text": "Raute", "correct": false, "because": "Entscheidung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente definiert DIN 66001?', 5, '[{"text": "Prozesssymbole", "correct": true, "because": "Ablauf darstellen"}, {"text": "Datenflusssymbole", "correct": true, "because": "Ein-/Ausgabe"}, {"text": "Farbcodes", "correct": false, "because": "Nicht standardisiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) DIN 66001 normt Ablaufpläne. b) Sie ist für Hardware relevant.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Software/Prozesse"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei DIN 66001?', 4, '[{"text": "Symboldefinition", "correct": false, "because": "Kern des Standards"}, {"text": "Ablauflogik", "correct": false, "because": "Wichtig für Pläne"}, {"text": "Papierfarbe", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob DIN 66001 noch oft genutzt wird?', 2, '[{"text": "Nein", "correct": true, "because": "Pseudocode häufiger"}, {"text": "Ja", "correct": false, "because": "Weniger gebräuchlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Symbol zeigt eine Entscheidung?', 3, '[{"text": "Raute", "correct": true, "because": "Ja/Nein-Abzweigung"}, {"text": "Kreis", "correct": false, "because": "Verbinder"}, {"text": "Quadrat", "correct": false, "because": "Prozess"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet DIN 66001?', 5, '[{"text": "Einheitliche Darstellung", "correct": true, "because": "Normierte Symbole"}, {"text": "Klarheit", "correct": true, "because": "Verständliche Pläne"}, {"text": "Schnellere Entwicklung", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) DIN 66001 ist für Flussdiagramme. b) Sie ersetzt UML. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "UML ist moderner"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für DIN 66001?', 4, '[{"text": "Symbole", "correct": false, "because": "Grundlage"}, {"text": "Ablaufstruktur", "correct": false, "because": "Essenziell"}, {"text": "Programmiersprache", "correct": true, "because": "Abstrakt"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist DIN 66001 nur für Programmierer?', 2, '[{"text": "Nein", "correct": true, "because": "Auch für Prozesse"}, {"text": "Ja", "correct": false, "because": "Breitere Nutzung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Symbole sind in DIN 66001 enthalten?', 4, '[{"text": "Rechteck", "correct": true, "because": "Prozessschritt"}, {"text": "Kreis", "correct": true, "because": "Verbinder"}, {"text": "Dreieck", "correct": false, "because": "Nicht standard"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass DIN 66001 veraltet ist. Stimmt das?', 2, '[{"text": "Ja", "correct": true, "because": "Weniger genutzt"}, {"text": "Nein", "correct": false, "because": "Noch bekannt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei DIN 66001?', 3, '[{"text": "Klarheit", "correct": true, "because": "Verständnis fördern"}, {"text": "Schnelligkeit", "correct": false, "because": "Genauigkeit zählt"}, {"text": "Farben", "correct": false, "because": "Nicht definiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) DIN 66001 normt Symbole. b) Sie ist für objektorientierte Programmierung.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Imperatives Paradigma"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nutzen hat DIN 66001?', 5, '[{"text": "Standardisierung", "correct": true, "because": "Einheitliche Pläne"}, {"text": "Lesbarkeit", "correct": true, "because": "Klar strukturiert"}, {"text": "Code-Erzeugung", "correct": false, "because": "Nicht direkt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei DIN 66001 unwichtig?', 3, '[{"text": "Symbolik", "correct": false, "because": "Kern des Standards"}, {"text": "Logische Folge", "correct": false, "because": "Essenziell"}, {"text": "Schriftart", "correct": true, "because": "Nicht normiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ersetzt DIN 66001 Pseudocode?', 3, '[{"text": "Nein", "correct": true, "because": "Ergänzende Ansätze"}, {"text": "Ja", "correct": false, "because": "Unterschiedliche Nutzung"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob DIN 66001 für UML relevant ist?', 2, '[{"text": "Nein", "correct": true, "because": "Andere Methode"}, {"text": "Ja", "correct": false, "because": "UML ist moderner"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Symbol markiert den Programmstart?', 4, '[{"text": "Abgerundetes Rechteck", "correct": true, "because": "Start/Ende"}, {"text": "Pfeil", "correct": false, "because": "Richtung"}, {"text": "Quadrat", "correct": false, "because": "Prozess"}]');
